// ---------- sample state & lifecycle ----------

func sampleVisibleTo(st *State, smp *Sample, u *User, role string) bool {
	switch role {
	case "dispatcher", "administrator":
		return true
	case "requester":
		return smp.RequesterID == u.UserID
	default:
		if smp.CurrentHolderID == u.UserID {
			return true
		}
		for _, id := range smp.ActiveAssignmentIDs {
			if as := st.Assignments[id]; as != nil && (as.WorkerID == u.UserID || as.OfferedTo == u.UserID) {
				return true
			}
		}
		for _, id := range smp.CompletedLegIDs {
			if as := st.Assignments[id]; as != nil && as.WorkerID == u.UserID {
				return true
			}
		}
		return false
	}
}

func sampleTimeline(st *State, smp *Sample) []interface{} {
	ids := map[string]bool{smp.SampleID: true, smp.RequestID: true}
	if smp.ActiveJourneyID != "" {
		ids[smp.ActiveJourneyID] = true
	}
	for _, as := range st.Assignments {
		if as.SampleID == smp.SampleID {
			ids[as.AssignmentID] = true
		}
	}
	for _, h := range st.Handoffs {
		if h.SampleID == smp.SampleID {
			ids[h.HandoffID] = true
		}
	}
	var entries []AuditEntry
	for _, e := range st.Audit {
		if ids[e.EntityID] {
			entries = append(entries, e)
		}
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].OccurredAt.Before(entries[j].OccurredAt) })
	out := []interface{}{}
	for i, e := range entries {
		m := timeline(e.ActorID, e.Role, e.Action, e.EntityType, e.EntityID, e.OccurredAt, e.Details)
		m["eventId"] = i + 1
		m["success"] = e.Success
		out = append(out, m)
	}
	return out
}

