// ---------- ui bootstrap ----------

func (a *App) readUIBootstrap(w http.ResponseWriter, r *http.Request) {
	u := getUser(r)
	sess := getSession(r)
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		a.expireOffersLocked(st)
		roles := u.Roles
