				"costUnits": c.CostUnits, "cooled": c.Cooled, "active": c.Active,
				"capacity": capJSON(c.Capacity),
			})
		}
		sampleTypes := []interface{}{}
		for _, t := range st.SampleTypes {
			sampleTypes = append(sampleTypes, sampleTypeJSON(t))
		}
		out = map[string]interface{}{
			"user": userInfo, "requesterSamples": samples,
			"operations": map[string]interface{}{
				"locations": locations, "connections": connections, "sampleTypes": sampleTypes,
				"stateVersion": st.StateVersion, "serviceabilityVersion": st.Serviceability.Version,
