// ---------- realtime events ----------

var upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}

func eventJSON(e Event) map[string]interface{} {
	return map[string]interface{}{
		"id": e.ID, "type": e.Type, "entityType": e.EntityType, "entityId": e.EntityID,
		"payload": e.Payload, "createdAt": timeStr(e.CreatedAt),
	}
}

func (a *App) streamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	since, _ := strconv.ParseInt(r.URL.Query().Get("since"), 10, 64)
	// websocket upgrade?
	if strings.Contains(strings.ToLower(r.Header.Get("Connection")), "upgrade") {
		// optional subprotocol lab-logistics-v1.<base64url(token)>
		if proto := r.Header.Get("Sec-WebSocket-Protocol"); proto != "" {
			parts := strings.SplitN(proto, ".", 2)
			if len(parts) == 2 {
				if raw, err := base64.RawURLEncoding.DecodeString(parts[1]); err == nil {
					tok := string(raw)
					var ok bool
					a.read(func(st *State) { _, ok = st.Sessions[tok] })
					if !ok {
						writeErr(w, errAPI(401, "unauthorized", "invalid session token in subprotocol"))
						return
					}
				}
			}
		}
		conn, err := upgrader.Upgrade(w, r, nil)
		if err != nil {
			return
		}
		defer conn.Close()
		ch := a.subscribe()
		defer a.unsubscribe(ch)
		// replay backlog
		var backlog []Event
		a.read(func(st *State) {
			for _, e := range st.Events {
				if e.ID > since {
					backlog = append(backlog, e)
				}
			}
		})
		for _, e := range backlog {
			if conn.WriteJSON(eventJSON(e)) != nil {
				return
			}
		}
		last := since
		if len(backlog) > 0 {
			last = backlog[len(backlog)-1].ID
		}
		for {
			select {
			case <-ch:
				var fresh []Event
				a.read(func(st *State) {
					for _, e := range st.Events {
						if e.ID > last {
							fresh = append(fresh, e)
						}
					}
				})
				for _, e := range fresh {
					if conn.WriteJSON(eventJSON(e)) != nil {
						return
					}
					last = e.ID
				}
			case <-time.After(30 * time.Second):
				if conn.WriteMessage(websocket.PingMessage, nil) != nil {
					return
				}
			}
		}
	}
	// long-poll JSON mode
	waitMs := 0
	if v := r.URL.Query().Get("waitMs"); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 {
			if n > 30000 {
				n = 30000
			}
			waitMs = n
		}
	}
	ch := a.subscribe()
	defer a.unsubscribe(ch)
	deadline := time.Now().Add(time.Duration(waitMs) * time.Millisecond)
	for {
		var evs []interface{}
		var cursor int64
		a.read(func(st *State) {
			evs = []interface{}{}
			cursor = since
			for _, e := range st.Events {
				if e.ID > since {
					evs = append(evs, eventJSON(e))
					cursor = e.ID
				}
			}
		})
		if len(evs) > 0 || waitMs == 0 || time.Now().After(deadline) {
			writeData(w, 200, map[string]interface{}{"events": evs, "cursor": cursor})
			return
		}
		select {
		case <-ch:
		case <-time.After(time.Until(deadline)):
		}
	}
}
"}

