{"command":"create","file_text":"import { useEffect, useRef } from "react";
import maplibregl from "maplibre-gl";
import { Protocol } from "pmtiles";
import "maplibre-gl/dist/maplibre-gl.css";

interface Marker {
  id: string;
  latitude: number;
  longitude: number;
  label: string;
  color?: string;
}

let protocolRegistered = false;

export default function MapView({ markers }: { markers: Marker[] }) {
  const ref = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);

  useEffect(() => {
    if (!ref.current || mapRef.current) return;
    if (!protocolRegistered) {
      const p = new Protocol();
      maplibregl.addProtocol("pmtiles", p.tile);
      protocolRegistered = true;
    }
    const map = new maplibregl.Map({
      container: ref.current,
      style: "/map-assets/style.json",
      center: [77.5946, 12.9716],
      zoom: 11,
    });
    map.addControl(new maplibregl.NavigationControl());
    mapRef.current = map;
    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    markersRef.current.forEach((m) => m.remove());
    markersRef.current = markers
      .filter((m) => m.latitude && m.longitude)
      .map((m) =>
        new maplibregl.Marker({ color: m.color ?? "#14335c" })
          .setLngLat([m.longitude, m.latitude])
          .setPopup(new maplibregl.Popup().setText(m.label))
          .addTo(map)
      );
  }, [markers]);

  return <div id="map" ref={ref} role="region" aria-label="Network map" />;
}
